"use strict";
exports.parts = function parts(s) {
  return s.split(",");
};
exports.pair = function pair() {
  return [7, "seven"];
};
exports.issueOf = function issueOf(msg) {
  return { code: "custom", path: ["items", 2, "name"], message: msg };
};
exports.nums = function nums() {
  return [10, 20, 30];
};
exports.headers = function headers() {
  return { "content-type": "text/plain", "x-id": "42" };
};
class Boom {
  constructor(msg) {
    this.msg = msg;
  }
}
exports.Boom = Boom;
exports.make = function make(kind) {
  return kind === "boom" ? new Boom("kaboom") : { plain: true };
};
exports.grep = function grep(re, items) {
  return items.filter(function (s) {
    return re.test(s);
  });
};
